#!/usr/bin/env bash
# Build one runner binary for the diagnosis comparisons and record its
# identity. Usage:
#
#   build.sh <worktree> <revision> <plain|phases> <out-dir>
#
# <worktree> must be a git worktree of this repository used only for these
# builds (its own target directory; never shared with another worktree). It
# is checked out at <revision>, cleanly. `phases` builds with the
# perf-phases feature: natively when the revision has it, otherwise with
# patches/<revision>-perf-phases.patch applied (generated by
# backport_phases.py). The binary and identity.json land in <out-dir>.
set -euo pipefail
W=$1 REV=$2 VARIANT=$3 OUT=$4
HERE=$(cd "$(dirname "$0")" && pwd)
case $VARIANT in plain|phases) ;; *) echo "variant: plain or phases" >&2; exit 2 ;; esac
cd "$W" || exit 1
[ "$(git rev-parse --show-toplevel)" = "$(cd "$W" && pwd -P)" ] || { echo "not a worktree root: $W" >&2; exit 1; }
# Back to a clean tree (a previous patch's new files are untracked; the
# ignored target directory stays).
git reset -q --hard
git clean -fdq
git checkout -q --detach "$REV"
git reset -q --hard "$REV"
[ -z "$(git status --porcelain)" ] || { echo "worktree not clean" >&2; exit 1; }
SHORT=$(git rev-parse --short=8 HEAD)
PATCH="" FEATURES=""
if [ "$VARIANT" = phases ]; then
  FEATURES=perf-phases
  if ! grep -q '^perf-phases' crates/runner/Cargo.toml; then
    PATCH="$HERE/patches/$SHORT-perf-phases.patch"
    [ -f "$PATCH" ] || { echo "no patch for $SHORT" >&2; exit 1; }
    git apply --check "$PATCH"
    git apply "$PATCH"
  fi
fi
cargo build --release -p runner ${FEATURES:+--features "$FEATURES"}
mkdir -p "$OUT"
cp target/release/runner "$OUT/runner"
python3 - "$OUT" "$SHORT" "$VARIANT" "$FEATURES" "$PATCH" <<'PY'
import hashlib, json, subprocess, sys, pathlib
out, rev, variant, features, patch = sys.argv[1:6]
sha = lambda p: hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
ident = {
    "revision": subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip(),
    "short": rev,
    "variant": variant,
    "features": features or None,
    "profile": "release",
    "patch": pathlib.Path(patch).name if patch else None,
    "patch_sha256": sha(patch) if patch else None,
    "cargo_lock_sha256": sha("Cargo.lock"),
    "rustc": subprocess.run(["rustc", "-vV"], capture_output=True, text=True).stdout,
    "cargo": subprocess.run(["cargo", "-V"], capture_output=True, text=True).stdout.strip(),
    "binary_sha256": sha(pathlib.Path(out) / "runner"),
}
(pathlib.Path(out) / "identity.json").write_text(json.dumps(ident, indent=2) + "\n")
print(json.dumps({k: ident[k] for k in ("short", "variant", "patch", "binary_sha256")}))
PY
git reset -q --hard
git clean -fdq
